+//go:build linux
+
+package engine
+
+import (
+	"fmt"
+	"io"
+	"os"
+	"time"
+)
+
+func (s *Store) trustActionsCLI(pos []string, input string, out io.Writer) error {
+	if len(pos) != 2 {
+		return fmt.Errorf("swarm trust show|config-preview|config-apply|mandate-create|mandate-revoke|request|approve|commit|reconcile|direct-write|elevate-integrity|export|anchor|verify")
+	}
+	action := pos[1]
+	switch action {
+	case "show":
+		v, err := s.trustView()
+		if err != nil {
+			return err
+		}
+		return printJSON(out, v)
+	case "export":
+		v, err := s.trustExport()
+		if err != nil {
+			return err
+		}
+		return printJSON(out, v)
+	case "anchor":
+		v, err := s.trustAnchor()
+		if err != nil {
+			return err
+		}
+		return printJSON(out, v)
+	}
+	if input == "" {
+		return fmt.Errorf("--input requis")
+	}
+	raw, err := readInput(input)
+	if err != nil {
+		return err
+	}
+	if action == "config-preview" || action == "config-apply" {
+		var change TrustConfigChange
+		if err = strict(raw, &change); err != nil {
+			return err
+		}
+		v, err := s.trustConfig(change, action == "config-preview")
+		if err != nil {
+			return err
+		}
+		return printJSON(out, v)
+	}
+	var cmd TrustCommand
+	if err = strict(raw, &cmd); err != nil {
+		return err
+	}
+	if action == "verify" {
+		v, err := verifyTrustCommand(cmd)
+		if err != nil {
+			return err
+		}
+		return printJSON(out, v)
+	}
+	cmd.original = append([]byte{}, raw...)
+	v, err := s.trustOperate(action, cmd, os.Getenv("SWARM_TRUST_TOKEN"), time.Now().UTC())
+	if err != nil {
+		return err
+	}
+	return printJSON(out, v)
+}

