package engine

import (
	"fmt"
	"io"
	"os"
	"time"
)

func (s *Store) trustActionsCLI(pos []string, input string, out io.Writer) error {
	if len(pos) != 2 {
		return fmt.Errorf("swarm trust show|config-preview|config-apply|mandate-create|mandate-revoke|request|approve|commit|reconcile|direct-write|elevate-integrity|export|anchor|verify")
	}
	action := pos[1]
	switch action {
	case "show":
		v, err := s.trustView()
		if err != nil {
			return err
		}
		return printJSON(out, v)
	case "export":
		v, err := s.trustExport()
		if err != nil {
			return err
		}
		return printJSON(out, v)
	case "anchor":
		v, err := s.trustAnchor()
		if err != nil {
			return err
		}
		return printJSON(out, v)
	}
	if input == "" {
		return fmt.Errorf("--input requis")
	}
	raw, err := readInput(input)
	if err != nil {
		return err
	}
	if action == "config-preview" || action == "config-apply" {
		var change TrustConfigChange
		if err = strict(raw, &change); err != nil {
			return err
		}
		v, err := s.trustConfig(change, action == "config-preview")
		if err != nil {
			return err
		}
		return printJSON(out, v)
	}
	var cmd TrustCommand
	if err = strict(raw, &cmd); err != nil {
		return err
	}
	if action == "verify" {
		v, err := verifyTrustCommand(cmd)
		if err != nil {
			return err
		}
		return printJSON(out, v)
	}
	cmd.original = append([]byte{}, raw...)
	v, err := s.trustOperate(action, cmd, os.Getenv("SWARM_TRUST_TOKEN"), time.Now().UTC())
	if err != nil {
		return err
	}
	return printJSON(out, v)
}
"}

{"path":"internal/engine/trust_actions_http.go","git_blob":"d03f9d03cae3c66e85705a6f0178ee6c9ab009e9","sha256":"88a758807779411757e154ecf151d27910ca4b04e704a559d2035a13949f891e","bytes":2089,"content":"//go:build linux

package engine

import (
	"io"
	"net/http"
	"strings"
	"time"
)

func registerTrustActionsHTTP(s *Store, mux *http.ServeMux, send func(http.ResponseWriter, any), fail func(http.ResponseWriter, error)) {
	mux.HandleFunc("/api/v1/trust-actions", func(w http.ResponseWriter, r *http.Request) {
		if r.Method == http.MethodGet {
			v, err := s.trustView()
			if err != nil {
				fail(w, err)
				return
			}
			send(w, v)
			return
		}
		if r.Method != http.MethodPost {
			http.Error(w, "GET ou POST requis", http.StatusMethodNotAllowed)
			return
		}
		r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
		raw, err := io.ReadAll(r.Body)
		if err != nil {
			fail(w, err)
			return
		}
		action := r.URL.Query().Get("action")
		if action == "config-preview" || action == "config-apply" {
			var change TrustConfigChange
			if err := strict(raw, &change); err != nil {
				fail(w, err)
				return
			}
			v, err := s.trustConfig(change, action == "config-preview")
			if err != nil {
				fail(w, err)
				return
			}
			send(w, v)
			return
		}
		if action == "export" {
			v, err := s.trustExport()
			if err != nil {
				fail(w, err)
				return
			}
			send(w, v)
			return
		}
		if action == "anchor" {
			v, err := s.trustAnchor()
			if err != nil {
				fail(w, err)
				return
			}
			send(w, v)
			return
		}
		var cmd TrustCommand
		if err := strict(raw, &cmd); err != nil {
			fail(w, err)
			return
		}
		if action == "verify" {
			v, err := verifyTrustCommand(cmd)
			if err != nil {
				fail(w, err)
				return
			}
			send(w, v)
			return
		}
		authorization := r.Header.Get("Authorization")
		if !strings.HasPrefix(authorization, "Bearer ") || strings.TrimSpace(authorization[7:]) == "" || strings.ContainsAny(authorization[7:], " \t\r\n") {
			fail(w, &CommandError{Code: "authorization_required", Message: "Authorization: Bearer <jeton> requis"})
			return
		}
		token := authorization[7:]
		cmd.original = append([]byte{}, raw...)
		v, err := s.trustOperate(action, cmd, token, time.Now().UTC())
		if err != nil {
			fail(w, err)
			return
		}
		send(w, v)
	})
}
"}

