package engine

import (
	"context"
	"crypto/subtle"
	"encoding/json"
	"fmt"
	"io"
	"io/fs"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	resources "swarm.local/companion"
	"time"
)

var cockpitWeb = resources.Web

type webRequest struct {
	Skills               []ActionSkillSelection `json:"skills,omitempty"`
	PreconditionEvidence string                 `json:"precondition_evidence,omitempty"`
	Turn                 string                 `json:"turn,omitempty"`
	Step                 int                    `json:"step,omitempty"`
	PlanHash             string                 `json:"plan_hash,omitempty"`
	Mode                 string                 `json:"mode,omitempty"`
	Level                string                 `json:"level,omitempty"`
	ModelPolicyHash      string                 `json:"model_policy_hash,omitempty"`
	PreviewToken         string                 `json:"preview_token,omitempty"`
	PlanBriefHash        string                 `json:"plan_brief_hash,omitempty"`
	Plan                 PlanReview             `json:"plan,omitempty"`
	References           []DialogueRef          `json:"references,omitempty"`
	ContextHash          string                 `json:"context_hash,omitempty"`
	Retex                Retex                  `json:"retex,omitempty"`
	Offset               int                    `json:"offset,omitempty"`
	Capture              bool                   `json:"capture_output"`
	Kind                 string                 `json:"kind"`
	Work                 string                 `json:"work"`
	Task                 string                 `json:"task"`
	Agent                string                 `json:"agent"`
	Event                string                 `json:"event_id"`
	Revision             int                    `json:"expected_revision"`
	Provider             string                 `json:"provider"`
	Role                 string                 `json:"role"`
	Workspace            string                 `json:"workspace"`
	Instruction          string                 `json:"instruction"`
	Path                 string                 `json:"path"`
	Name                 string                 `json:"name"`
	Note                 string                 `json:"note"`
	Author               string                 `json:"author"`
	Decision             string                 `json:"decision"`
	Request              Request                `json:"request"`
	RoleModel            RoleModelRequest       `json:"role_model"`
	TaskModel            TaskModelRequest       `json:"task_model"`
	Quotas               QuotaChange            `json:"quotas"`
	Budget               Budget                 `json:"budget"`
	ValidationPolicy     ValidationPolicyChange `json:"validation_policy,omitempty"`
	Autonomy             string                 `json:"autonomy,omitempty"`
	Slots                int                    `json:"slots,omitempty"`
	LifecycleAction      string                 `json:"lifecycle_action,omitempty"`
	RetentionDays        int                    `json:"retention_days,omitempty"`
}

func (s *Store) webAction(r webRequest) (any, error) {
	if r.Kind == "role-model-preview" || r.Kind == "role-model" {
		q := r.RoleModel
		q.Schema = 1
		q.Revision = r.Revision
		q.EventID = r.Event
		if r.Kind == "role-model-preview" {
			return s.previewRoleModel(r.Work, q)
		}
		return s.configureRoleModel(r.Work, q)
	}
	if r.Kind == "task-model-preview" || r.Kind == "task-model" {
		q := r.TaskModel
		q.Schema = 1
		q.Revision = r.Revision
		q.EventID = r.Event
		q.Task = r.Task
		if r.Kind == "task-model-preview" {
			return s.previewTaskModel(r.Work, q)
		}
		return s.configureTaskModel(r.Work, q)
	}
	if r.Kind == "quotas-preview" || r.Kind == "quotas" {
		q := r.Quotas
		q.Schema = 1
		q.EventID = r.Event
		q.Revision = r.Revision
		if r.Kind == "quotas-preview" {
			return s.previewQuotas(r.Work, q)
		}
		return s.configureQuotas(r.Work, q)
	}
	if r.Kind == "budget" || r.Kind == "budget-preview" {
		change := BudgetChange{Schema: 1, EventID: r.Event, Revision: r.Revision, Budget: r.Budget}
		if r.Kind == "budget-preview" {
			return s.previewBudget(r.Work, change)
		}
		return s.configureBudget(r.Work, change)
	}
	if r.Kind == "lifecycle-preview" || r.Kind == "lifecycle-apply" {
		request := LifecycleRequest{Schema: 1, EventID: r.Event, Revision: r.Revision, Action: r.LifecycleAction, RetentionDays: r.RetentionDays, PreviewToken: r.PreviewToken}
		if r.Kind == "lifecycle-preview" {
			return s.lifecyclePreview(r.Work, request)
		}
		return s.lifecycleApply(r.Work, request)
	}
	if r.Kind == "validation-policy-preview" || r.Kind == "validation-policy-apply" {
		change := r.ValidationPolicy
		change.Schema, change.TaskID, change.Revision = 1, r.Task, r.Revision
		if r.Kind == "validation-policy-preview" {
			return s.previewValidationPolicy(r.Work, change)
		}
		change.EventID = r.Event
		return s.applyValidationPolicy(r.Work, change)
	}
	if r.Kind == "assist-action-preview" {
		return s.assistActionPlan(r.Work, r.Turn, r.Step)
	}
	if r.Kind == "assist-action-apply" {
		return s.applyAssistAction(r.Work, r.Turn, r.Step, r.PlanHash)
	}
	if r.Kind == "mission-start" || r.Kind == "mission-preview" {
		if r.Kind == "mission-start" && r.Event != "" {
			var existing int
			if err := s.db.QueryRow("SELECT count(*) FROM events WHERE id=?", r.Event).Scan(&existing); err != nil {
				return nil, err
			} else if existing > 0 {
				w, err := s.get(r.Work)
				if err != nil {
					return nil, err
				}
				profile := LaunchProfile{Role: "worker"}
				if w.Profile != nil {
					profile = *w.Profile
				}
				profile.Provider, profile.Workspace, profile.Level = r.Provider, r.Workspace, r.Level
				profile.Updated, profile.Actor = "", ""
				if err = s.configureMission(r.Work, profile, r.Slots, r.Revision, r.Event, r.PreviewToken); err != nil {
					return nil, err
				}
				return s.missionStatus(r.Work)
			}
		}
		ps, err := s.providers()
		if err != nil {
			return nil, err
		}
		_, route, err := resolveModel(ps.Providers[r.Provider], r.Level, "work")
		if err != nil {
			return nil, err
		}
		if r.ModelPolicyHash != "" && (route == nil || route.PolicyHash != r.ModelPolicyHash) {
			return nil, fmt.Errorf("Politique de modèle modifiée : examiner le choix à nouveau")
		}
		w, err := s.get(r.Work)
		if err != nil {
			return nil, err
		}
		profile := LaunchProfile{Role: "worker"}
		if w.Profile != nil {
			profile = *w.Profile
		}
		profile.Provider = r.Provider
		profile.Workspace = r.Workspace
		profile.Level = r.Level
		profile.Updated = ""
		profile.Actor = ""
		launchPreview, err := s.missionLaunchPreview(r.Work, profile, r.Slots)
		if err != nil {
			return nil, err
		}
		if r.Kind == "mission-preview" && launchPreview.Revision != r.Revision {
			return nil, fmt.Errorf("Travail modifié : examiner le nouvel aperçu avant de confirmer")
		}
		if r.Kind == "mission-preview" {
			return launchPreview, nil
		}
		if r.PreviewToken == "" || r.PreviewToken != launchPreview.Token {
			return nil, fmt.Errorf("L’aperçu confirmé n’est plus courant : examiner le nouvel aperçu avant de confirmer")
		}
		err = s.configureMission(r.Work, profile, r.Slots, r.Revision, r.Event, r.PreviewToken)
		if err != nil {
			return nil, err
		}
		return s.missionStatus(r.Work)
	}
	if r.Kind == "launch-preview" {
		return s.launchEligibility(r), nil
	}
	if r.Kind == "resume-launch" {
		a, created, e := s.resumePreparedLaunch(r.Work, r.Agent, r.Revision)
		if e == nil && (created || a.Status == "queued") {
			e = s.spawnAgent(a)
		}
		return a, e
	}
	if r.Kind == "preflight" {
		result, _ := s.preflightLaunch(r.Work, Launch{Skills: r.Skills, Mode: r.Mode, Level: r.Level, Provider: r.Provider, Workspace: r.Workspace})
		return result, nil
	}
	if r.Kind == "plan-read" {
		return s.readPlan(r.Work, r.Task)
	}
	if r.Kind == "plan-commit" {
		return s.commitPlan(r.Work, r.Event, r.Revision, r.Plan)
	}
	if r.Kind == "task" {
		r.Request.Schema = 1
		r.Request.EventID = r.Event
		r.Request.Revision = r.Revision
		r.Request.ID = r.Task
		// Personne ne se declare moteur depuis l'exterieur : ce qui arrive par
		// le reseau est un geste humain, quel que soit le champ envoye.
		r.Request.Origin = ""
		return s.executeRequest(r.Work, "task.update", r.Request)
	}
	if strings.HasPrefix(r.Kind, "retex-") {
		return s.retexAction(r)
	}
	if r.Kind == "dialogue-search" {
		w, e := s.get(r.Work)
		if e != nil {
			return nil, e
		}
		return searchDialogue(w, r.Note, r.Offset), nil
	}
	if r.Kind == "context-preview" {
		a, _, e := s.prepareLaunch(r.Work, Launch{Level: r.Level, ModelPolicyHash: r.ModelPolicyHash, PlanBriefHash: r.PlanBriefHash, Brainstorm: true, Schema: 1, EventID: r.Event, Revision: r.Revision, Provider: r.Provider, Workspace: r.Workspace, Instruction: r.Instruction, Capture: r.Capture, References: r.References}, true)
		return a, e
	}
	if r.Kind == "start" || r.Kind == "brainstorm" {
		if r.Kind == "brainstorm" && r.ContextHash == "" {
			return nil, fmt.Errorf("Examiner le contexte avant envoi.")
		}
		a, created, e := s.prepare(r.Work, Launch{Skills: r.Skills, Mode: r.Mode, Level: r.Level, ModelPolicyHash: r.ModelPolicyHash, PlanBriefHash: r.PlanBriefHash, References: r.References, ContextHash: r.ContextHash, Brainstorm: r.Kind == "brainstorm", Schema: 1, EventID: r.Event, Revision: r.Revision, TaskID: r.Task, Provider: r.Provider, Role: r.Role, Workspace: r.Workspace, Instruction: r.Instruction, Capture: r.Capture})
		if e != nil {
			return nil, e
		}
		if created {
			e = s.spawnAgent(a)
		}
		return a, e
	}
	// prepare checks replay identity before the revision: a lost response must
	// return the existing retry rather than create another attempt.
	if r.Kind == "retry" {
		a, e := s.agent(r.Agent)
		if e != nil {
			return nil, e
		}
		if a.WorkID != r.Work || (r.Task != "" && a.TaskID != r.Task) || activeAgent(a) {
			return nil, fmt.Errorf("tentative incompatible")
		}
		if r.Level == "" && a.ModelRoute != nil {
			r.Level = a.ModelRoute.Level
		}
		next, created, e := s.prepare(r.Work, Launch{Skills: r.Skills, PreconditionEvidence: r.PreconditionEvidence, Mode: a.Mode, Level: r.Level, ModelPolicyHash: r.ModelPolicyHash, Schema: 1, EventID: r.Event, Revision: r.Revision, TaskID: a.TaskID, Provider: a.Provider, Role: a.Role, Workspace: a.CWD, Instruction: r.Instruction, Previous: a.ID, Parent: a.Parent, Capture: r.Capture})
		if e == nil && created {
			e = s.spawnAgent(next)
		}
		return next, e
	}
	if (r.Kind == "stop" || r.Kind == "reconcile") && r.Event != "" {
		return s.agentCommandReceipt(r)
	}
	w, e := s.get(r.Work)
	if e != nil {
		return nil, e
	}
	if r.Revision != w.Revision {
		return nil, &CommandError{Code: "revision_conflict", Message: "Le travail a changé ; actualiser puis confirmer.", Retryable: true}
	}
	switch r.Kind {
	case "stop", "reconcile":
		a, e := s.agent(r.Agent)
		if e != nil {
			return nil, e
		}
		if a.WorkID != r.Work || (r.Task != "" && a.TaskID != r.Task) {
			return nil, fmt.Errorf("agent hors travail")
		}
		if r.Kind == "stop" {
			e = s.stopAgent(a.ID)
		} else {
			e = s.reconcile(a.ID)
		}
		return map[string]string{"message": "Demande enregistrée ; vérifier l’état observé."}, e
	case "adopt-brief":
		return s.adoptBrief(r.Work, r.Task, r.Path, r.Note, r.Event, r.Revision)
	case "submit":
		e = s.submitReportAt(r.Work, r.Task, r.Path, r.Revision, "")
	case "gate-preview", "gate":
		t, err := w.task(r.Task)
		if err != nil {
			return nil, err
		}
		if r.Kind == "gate" && strings.TrimSpace(r.Name) == "" {
			return nil, fmt.Errorf("Nom de la gate requis : nom humain de cette évaluation.")
		}
		d := &taskDialog{task: *t, reportPath: r.Path, gateName: strings.TrimSpace(r.Name)}
		if e = s.previewGate(r.Work, d); e != nil {
			return nil, e
		}
		if r.Kind == "gate-preview" {
			return map[string]string{"preview": d.review}, nil
		}
		d.gateRevision = r.Revision
		e = s.recordDialogGate(r.Work, d)
	case "override":
		e = s.overrideReviewedTaskAt(r.Work, r.Task, r.Note, r.Revision)
	case "decision":
		e = s.resolveDecision(r.Work, r.Decision, operatorIdentity(), r.Note)
	case "pause":
		e = s.pause(r.Work, true)
	case "unpause":
		if e = s.pause(r.Work, false); e == nil {
			// Reprendre les départs relance immédiatement l'ordonnanceur.
			_, e = s.dispatch(r.Work)
		}
	case "profile":
		e = s.setProfile(r.Work, r.Task, LaunchProfile{Provider: r.Provider, Role: r.Role, Workspace: r.Workspace,
			Instruction: r.Instruction, Level: r.Level, Capture: r.Capture}, r.Revision)
	case "autonomy":
		if e = s.setAutonomy(r.Work, r.Autonomy, r.Slots); e == nil {
			_, e = s.dispatch(r.Work)
		}
	case "mission-pause":
		e = s.pause(r.Work, true)
	case "mission-resume":
		var p MissionPolicy
		p, e = s.missionPolicy(r.Work)
		if e == nil && !p.Enabled {
			e = fmt.Errorf("Autorisez d’abord la mission continue")
		}
		if e == nil {
			e = s.setAutonomy(r.Work, autonomyAuto, s.slots(r.Work))
		}
		if e == nil {
			e = s.pause(r.Work, false)
		}
	case "dispatch":
		launched, err := s.dispatch(r.Work)
		if err != nil {
			return nil, err
		}
		return map[string]any{"launched": dispatchedIDs(launched),
			"message": fmt.Sprintf("%d départ(s) automatique(s) ; consulter le journal du travail pour les refus.", len(launched))}, nil
	case "ooda":
		r.Request.Schema = 1
		r.Request.EventID = r.Event
		r.Request.Revision = r.Revision
		r.Request.Owner = operatorIdentity()
		return s.executeRequest(r.Work, "ooda", r.Request)
	default:
		return nil, fmt.Errorf("action inconnue")
	}
	return map[string]string{"message": "Action enregistrée."}, e
}
func newWebHandler(s *Store, host, token string) http.Handler {
