	mux.Handle("/", http.FileServer(http.FS(files)))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Cache-Control", "no-store")
		w.Header().Set("X-Content-Type-Options", "nosniff")
		w.Header().Set("Referrer-Policy", "no-referrer")
		w.Header().Set("Content-Security-Policy", "default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'")
		if r.Host != host {
			http.Error(w, "Hôte refusé", 403)
			return
		}
		if sessionPolicyError != nil {
			http.Error(w, "Configuration de session invalide", 500)
			return
		}
		if r.URL.Path == "/login" {
			webLogin(w, r, host, token, sessionMaxAge)
			return
		}
		if (r.Method == "GET" || r.Method == "HEAD") && (r.URL.Path == "/access.css" || r.URL.Path == "/access.js" || r.URL.Path == "/wattson_themes.css" || r.URL.Path == "/swarm-design.css" || r.URL.Path == "/swarm-logo.png") {
			mux.ServeHTTP(w, r)
			return
		}
		if r.URL.Path == automationExternalPath {
			mux.ServeHTTP(w, r)
			return
		}
		if strings.HasPrefix(r.URL.Path, "/session/") {
			if r.Method != "GET" || !same(strings.TrimPrefix(r.URL.Path, "/session/"), token) {
				http.Error(w, "Session refusée", 403)
				return
			}
			http.SetCookie(w, webSessionCookie(host, token, sessionMaxAge))
			target := "/"
			if r.URL.Query().Get("view") == "prepare" {
				target = "/prepare.html"
				if id := r.URL.Query().Get("id"); preparationKey(id) {
					target += "?id=" + id
				}
			} else if id := r.URL.Query().Get("work"); id != "" {
				if !safeName(id) {
					http.Error(w, "Travail invalide", 400)
					return
				}
				target = "/?work=" + id
			}
			if language := r.URL.Query().Get("lang"); language == "fr" || language == "en" {
				separator := "?"
				if strings.Contains(target, "?") {
					separator = "&"
				}
				target += separator + "lang=" + language
			}
			http.Redirect(w, r, target, http.StatusSeeOther)
			return
		}
		cookie, e := r.Cookie("swarm_session_" + hash([]byte(host))[:12])
		if e == http.ErrNoCookie {
			cookie, e = r.Cookie("swarm_session")
		} // accept existing clients until they reopen their session link
		if e != nil || !same(cookie.Value, token) {
			if r.Method == "GET" && (r.URL.Path == "/" || r.URL.Path == "/index.html" || r.URL.Path == "/prepare.html" || r.URL.Path == "/plan.html") {
				webAccessPage(w, r, 200, "")
				return
			}
			http.Error(w, "Session requise : reconnectez-vous au cockpit.", 403)
			return
		}
		if r.Method != "GET" && r.Method != "HEAD" {
			if r.Header.Get("Origin") != "http://"+host || !same(r.Header.Get("X-Swarm-CSRF"), token) {
				http.Error(w, "Origine ou confirmation de session refusée", 403)
				return
			}
		}
		if r.URL.Path == "/api/v1/session" {
			send(w, map[string]string{"csrf": token})
			return
		}
		// Only embedded static assets may be cached. Authenticate first; keep all
		// documents, API replies and session pages no-store. Content ETags prevent
		// fixed entry files from staying stale after replacing the binary.
		asset := strings.TrimPrefix(r.URL.Path, "/")
		if (r.Method == "GET" || r.Method == "HEAD") && fs.ValidPath(asset) && (strings.HasSuffix(asset, ".js") || strings.HasSuffix(asset, ".css") || strings.HasSuffix(asset, ".woff2")) {
			if content, err := cockpitWeb.ReadFile("web/" + asset); err == nil {
				etag := `"` + hash(content) + `"`
				w.Header().Set("ETag", etag)
				w.Header().Set("Cache-Control", "private, no-cache")
				if r.Header.Get("If-None-Match") == etag {
					w.WriteHeader(http.StatusNotModified)
					return
				}
			}
		}
		mux.ServeHTTP(w, r)
	})
}
func (s *Store) serveWeb(address string, out io.Writer) error {
	if _, err := s.webSessionLifetime(); err != nil {
		return err
	}
	if _, err := os.Stat(filepath.Join(s.root, ".swarm", "providers.json")); os.IsNotExist(err) {
		if err = s.initProviders(); err != nil && !os.IsExist(err) {
			return err
		}
	}
	if address == "" {
		address = "127.0.0.1:0"
	}
	host, _, e := net.SplitHostPort(address)
	if e != nil {
		return e
	}
	if host != "127.0.0.1" && host != "::1" {
		return fmt.Errorf("écoute locale loopback uniquement")
	}
	listener, e := net.Listen("tcp", address)
	if e != nil {
		return e
	}
	defer listener.Close()
	if err := s.assistReconcile(); err != nil {
		return err
	}
	token, e := s.webSessionToken(listener.Addr().String())
	if e != nil {
		return e
	}
	fmt.Fprintf(out, "Cockpit local : http://%s/session/%s\nArrêter ce serveur ne coupe pas les agents.\n", listener.Addr(), token)
	server := &http.Server{Handler: newWebHandler(s, listener.Addr().String(), token), ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 10 * time.Second, IdleTimeout: 30 * time.Second}
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go s.missionLoop(ctx)
	return server.Serve(listener)
}
"}

