html { scrollbar-color: var(--wattson-ligne) var(--wattson-fond); scroll-padding-top: 24px; }
body, html[data-theme="etat"] body { background: var(--wattson-fond); font-family: var(--wattson-police); }
h1,h2,h3,h4,p,summary,button,a,label { overflow-wrap: anywhere; }
button,input,select,textarea { border-radius: var(--wattson-rayon-controle); }
