func now() string { return time.Now().UTC().Format(time.RFC3339Nano) }
func newID(prefix string) string {
	b := make([]byte, 12)
	if _, e := rand.Read(b); e != nil {
		panic(e)
	}
	return prefix + hex.EncodeToString(b)
}
func nonempty(s string) bool { return strings.TrimSpace(s) != "" }
func require(ok bool, msg string) error {
	if !ok {
		return fmt.Errorf("%s", msg)
	}
	return nil
}
func (w *Work) task(id string) (*Task, error) {
	for i := range w.Tasks {
		if w.Tasks[i].ID == id {
			return &w.Tasks[i], nil
		}
	}
	return nil, fmt.Errorf("tâche inconnue : %s", id)
}
func safeName(s string) bool {
	if s == "" || len(s) > 100 {
		return false
	}
	for _, r := range s {
		if !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '-' || r == '_') {
			return false
		}
	}
	return true
}

// Resolve the authorized root and targets in the same physical namespace.
// A retained alias after a project move must not make its own files outsiders.
// Child symlinks still pass the existing containment checks below.
func canonicalProjectRoot(root string) (string, error) {
	abs, err := filepath.Abs(root)
	if err != nil {
		return "", err
	}
	return filepath.EvalSymlinks(abs)
}

// Only an alias of the complete authorized project root is compatible with
// retained ownership. A redirected child directory is a different identity.
func canonicalOwnedProjectPath(root, path string) (string, error) {
	canonical, err := canonicalProjectRoot(root)
	if err != nil {
		return "", err
	}
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return "", fmt.Errorf("chemin absolu normalisé requis")
	}
	var ancestors []string
	for p := path; ; p = filepath.Dir(p) {
		ancestors = append(ancestors, p)
		if filepath.Dir(p) == p {
			break
		}
	}
	// Inspect from outside to inside: a child link back to the root must not be
	// mistaken for another authorized project-root alias.
	for i := len(ancestors) - 1; i >= 0; i-- {
		prefix, e := filepath.EvalSymlinks(ancestors[i])
		if e != nil || prefix != canonical {
			continue
		}
		rel, e := filepath.Rel(ancestors[i], path)
		if e != nil {
			return "", e
		}
		actual, e := filepath.EvalSymlinks(path)
		if e != nil {
			return "", e
		}
		if actual != filepath.Join(canonical, rel) {
			return "", fmt.Errorf("chemin attribué redirigé")
		}
		return actual, nil
	}
	return "", fmt.Errorf("chemin attribué hors projet")
}

func localFile(root, name string) (string, error) {
	if !nonempty(name) || filepath.IsAbs(name) {
		return "", fmt.Errorf("chemin relatif requis : %s", name)
	}
	root, e := canonicalProjectRoot(root)
	if e != nil {
		return "", e
	}
	resolved, e := filepath.EvalSymlinks(filepath.Join(root, name))
	if e != nil {
		return "", e
	}
	rel, e := filepath.Rel(root, resolved)
	if e != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("chemin hors projet : %s", name)
	}
	st, e := os.Stat(resolved)
	if e != nil {
		return "", e
	}
	if !st.Mode().IsRegular() {
		return "", fmt.Errorf("fichier régulier requis : %s", name)
	}
	return resolved, nil
}
func atomicWrite(path string, data []byte) error {
	f, e := os.CreateTemp(filepath.Dir(path), ".swarm-write-")
	if e != nil {
		return e
	}
	name := f.Name()
	defer os.Remove(name)
	if _, e = f.Write(data); e != nil {
		f.Close()
		return e
	}
	if e = f.Sync(); e != nil {
		f.Close()
		return e
	}
	if e = f.Close(); e != nil {
		return e
	}
	return os.Rename(name, path)
}
"}

