	if version < 30 {
		if version != 0 {
			if e = migrationBackup(db, filepath.Join(dir, newID("state-pre-v30-")+".db")); e != nil {
				return fail(e)
			}
		}
		if _, e = db.Exec("PRAGMA user_version=30"); e != nil {
			return fail(e)
		}
	}
	// Version 31 fences the attributed internal-command budget receipt.
	if version < 31 {
		if version != 0 {
			if e = migrationBackup(db, filepath.Join(dir, newID("state-pre-v31-")+".db")); e != nil {
				return fail(e)
			}
		}
		if _, e = db.Exec("PRAGMA user_version=31"); e != nil {
			return fail(e)
		}
	}
	// Fence cycle-policy semantics and quota audit fields from older decoders.
	// Keep every original Work body and explicitly configured ceiling unchanged.
	if version < 32 {
		if version != 0 {
			if e = migrationBackup(db, filepath.Join(dir, newID("state-pre-v32-")+".db")); e != nil {
				return fail(e)
			}
		}
		if _, e = db.Exec("PRAGMA user_version=32"); e != nil {
			return fail(e)
		}
	}
	if e = os.Chmod(path, 0600); e != nil {
		return fail(e)
	}
	return s, nil
}

// SQLite otherwise creates VACUUM INTO destinations with the process umask,
// which may expose a migration snapshot containing credentials or mission data.
func migrationBackup(db *sql.DB, path string) error {
	file, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
	if err != nil {
		return err
	}
	if err = file.Close(); err != nil {
		_ = os.Remove(path)
		return err
	}
	if _, err = db.Exec("VACUUM INTO ?", path); err != nil {
		_ = os.Remove(path)
		return err
	}
	return nil
}

// Les réglages d'autonomie s'ajoutent à une table existante : selon la version
// d'origine, les colonnes peuvent déjà être présentes. Vérifier avant d'ajouter,
// plutôt que de supposer un chemin de migration unique.
func migrateAutonomy(db *sql.DB) error {
	existing := map[string]bool{}
	rows, e := db.Query("PRAGMA table_info(cockpit_controls)")
	if e != nil {
		return e
	}
	for rows.Next() {
		var cid int
		var name, kind string
		var notnull, primary int
		var def any
		if e = rows.Scan(&cid, &name, &kind, &notnull, &def, &primary); e != nil {
			rows.Close()
			return e
		}
		existing[name] = true
	}
	rows.Close()
	if e = rows.Err(); e != nil {
		return e
	}
	statements := []string{}
	if !existing["autonomy"] {
		statements = append(statements, "ALTER TABLE cockpit_controls ADD COLUMN autonomy TEXT NOT NULL DEFAULT 'autonome'")
	}
	if !existing["slots"] {
		statements = append(statements, "ALTER TABLE cockpit_controls ADD COLUMN slots INTEGER NOT NULL DEFAULT 2")
	}
	for _, statement := range statements {
		if _, e = db.Exec(statement); e != nil {
			return e
		}
	}
	_, e = db.Exec("PRAGMA user_version=5")
	return e
}

// Les fermetures écrites par le moteur partageaient le type « decision » avec
// les acquittements humains, donc le fil d'activité les attribuait à
// l'opérateur. Le type est désormais distinct à l'écriture ; les lignes déjà
// enregistrées sont reclassées à partir de leur propre message, qui contient
// l'auteur — ce n'est pas une supposition, c'est relire ce qui a été écrit.
func migrateDecisionAuthorKind(db *sql.DB) error {
	if _, e := db.Exec(`UPDATE cockpit_events SET kind='decision.moteur'
		WHERE kind='decision' AND instr(message, ' : ') > 0
		AND substr(message, instr(message, ' : ') + 3, length('moteur : ')) = 'moteur : '`); e != nil {
		return e
	}
	_, e := db.Exec("PRAGMA user_version=6")
	return e
}

func (s *Store) get(id string) (Work, error) {
	var b []byte
	var w Work
	e := s.db.QueryRow("SELECT body FROM works WHERE id=?", id).Scan(&b)
	if e != nil {
		return w, fmt.Errorf("travail %s : %w", id, e)
	}
	e = json.Unmarshal(b, &w)
	return w, e
}
func (s *Store) list() ([]Work, error) {
	rs, e := s.db.Query("SELECT body FROM works ORDER BY rowid DESC")
	if e != nil {
		return nil, e
	}
	defer rs.Close()
	out := []Work{}
	for rs.Next() {
		var b []byte
		if e = rs.Scan(&b); e != nil {
			return nil, e
		}
		var w Work
		if e = json.Unmarshal(b, &w); e != nil {
			return nil, e
		}
		out = append(out, w)
	}
	return out, rs.Err()
}
func (s *Store) events(id string) ([]Event, error) {
	rs, e := s.db.Query("SELECT id,work_id,revision,kind,at,payload FROM events WHERE work_id=? ORDER BY revision", id)
	if e != nil {
		return nil, e
	}
	defer rs.Close()
	out := []Event{}
	for rs.Next() {
		var v Event
		if e = rs.Scan(&v.ID, &v.WorkID, &v.Revision, &v.Kind, &v.At, &v.Payload); e != nil {
			return nil, e
		}
		out = append(out, v)
	}
	return out, rs.Err()
}
func gitState(root string) GitState {
	run := func(args ...string) string {
		c := exec.Command("git", append([]string{"-C", root}, args...)...)
		b, e := c.Output()
		if e != nil {
			return ""
		}
		return strings.TrimSpace(string(b))
	}
	return GitState{run("rev-parse", "HEAD"), run("branch", "--show-current"), run("status", "--porcelain", "--untracked-files=normal")}
}

// The event key is an idempotency key, checked before optimistic concurrency.
func (s *Store) mutate(id, kind, event string, expected int, request []byte, fn func(*Work) error) (Work, error) {
	return s.mutateWithHook(id, kind, event, expected, request, fn, nil)
}

func (s *Store) mutateWithHook(id, kind, event string, expected int, request []byte, fn func(*Work) error, hook func(*sql.Tx, *Work) error) (Work, error) {
	policy, err := s.storageRetryPolicy()
	if err != nil {
		return Work{}, err
	}
	for attempt := 0; ; attempt++ {
		w, err := s.mutateWithHookOnce(id, kind, event, expected, request, fn, hook)
		var busy *sqlite.Error
		if !errors.As(err, &busy) || busy.Code()&255 != 5 || attempt >= policy.Retries {
			return w, err
		}
		time.Sleep(time.Duration(policy.DelayMS) * time.Millisecond)
	}
}

func (s *Store) mutateWithHookOnce(id, kind, event string, expected int, request []byte, fn func(*Work) error, hook func(*sql.Tx, *Work) error) (Work, error) {
	var w Work
	if !safeName(event) {
		return w, fmt.Errorf("event_id obligatoire (lettres, chiffres, tirets)")
	}
	tx, e := s.db.Begin()
	if e != nil {
		return w, e
	}
	defer tx.Rollback()
	// Every mutation reads then writes. Reserve the writer before any reads;
	// a per-kind allowlist leaves new and ordinary mutations exposed to
	// BUSY_SNAPSHOT, which busy_timeout cannot repair. This no-op also works
	// for creation (no matching row) and rolls back on failed guards.
	if _, e = tx.Exec("UPDATE works SET revision=revision WHERE id=?", id); e != nil {
		return w, e
	}

	// Opening-time validation does not protect a process whose connection
	// predates a storage upgrade. Check under the writer reservation, before
	// decoding or rewriting Work JSON or invoking mutation hooks.
	var version int
	if e = tx.QueryRow("PRAGMA user_version").Scan(&version); e != nil {
		return w, e
	}
	if version != schemaVersion {
		return w, &CommandError{Code: "storage_version_conflict", Message: fmt.Sprintf("Stockage version %d, processus version %d : écriture refusée. Arrêtez les anciens processus puis utilisez le CLI du serveur actif.", version, schemaVersion)}
	}

	var oldID, oldKind string
	var oldRequest []byte
	e = tx.QueryRow("SELECT work_id,kind,request FROM events WHERE id=?", event).Scan(&oldID, &oldKind, &oldRequest)
	if e == nil {
		if (id != "" && oldID != id) || oldKind != kind || string(oldRequest) != string(request) {
			return w, &CommandError{Code: "event_conflict", Message: "event_id déjà utilisé pour un contenu différent"}
		}
		var b []byte
		if e = tx.QueryRow("SELECT body FROM works WHERE id=?", oldID).Scan(&b); e != nil {
			return w, e
		}
		e = json.Unmarshal(b, &w)
		return w, e
	}
	if !errors.Is(e, sql.ErrNoRows) {
		return w, e
	}
	create := kind == "work.create"
	if create {
		if expected != 0 {
			return w, fmt.Errorf("création : expected_revision doit valoir 0")
		}
		w = Work{Schema: 1, ID: newID("w-"), Created: now(), Tasks: []Task{}}
	} else {
		var b []byte
		if e = tx.QueryRow("SELECT body FROM works WHERE id=?", id).Scan(&b); e != nil {
			return w, e
		}
		if e = json.Unmarshal(b, &w); e != nil {
			return w, e
		}
		if w.Revision != expected {
			return w, &CommandError{Code: "revision_conflict", Message: fmt.Sprintf("révision périmée : attendue %d, courante %d ; relire le travail", expected, w.Revision), Retryable: true}
		}
	}
	if w.Planning != nil && (kind == "work.update" || kind == "task.add") {
		return w, fmt.Errorf("mission hiérarchique : modifier le plan via une décision versionnée")
	}
	if kind == "work.update" {
		var count int
		if e = tx.QueryRow("SELECT count(*) FROM agents WHERE work_id=? AND status IN ('queued','starting','running','stopping')", id).Scan(&count); e != nil {
			return w, e
		}
		if count > 0 {
			return w, fmt.Errorf("arrêter et réconcilier les agents avant de modifier le contrat du travail")
		}
	}
	// The ownership guard uses this transaction, after replay and revision checks.
	if kind == "task.update" || kind == "task.submit" {
		var r Request
		if e = json.Unmarshal(request, &r); e != nil {
			return w, e
		}
		if w.Planning != nil && r.editsDefinition() {
			if kind != "task.update" {
				return w, fmt.Errorf("réviser explicitement le contrat via task update avant remise")
			}
			var paused bool
			if e = tx.QueryRow("SELECT paused FROM cockpit_controls WHERE work_id=?", id).Scan(&paused); e != nil || !paused {
				return w, fmt.Errorf("révision de contrat : mission doit être en pause publique")
			}
			if e = validateHierarchicalContractRevision(&w, r); e != nil {
				return w, e
			}
		}
		if r.Status == "running" {
			if e = preparationLaunchGuard(tx, id, r.ID); e != nil {
				return w, e
			}
		}
		if r.Status != "" || r.editsDefinition() {
			var count int
			if e = tx.QueryRow("SELECT count(*) FROM agents WHERE work_id=? AND (task_id=? OR ?) AND status IN ('queued','starting','running','stopping')", id, r.ID, r.editsDefinition()).Scan(&count); e != nil {
				return w, e
			}
			if count > 0 {
				return w, &CommandError{Code: "active_agent", Message: "arrêter et réconcilier les agents concernés avant modification du statut ou du contrat"}
			}
		}
	}
	beforePlanning := map[string]string{}
	if w.Planning != nil {
		for _, task := range w.Tasks {
			beforePlanning[task.ID] = task.Status
		}
	}
	if e = fn(&w); e != nil {
		return w, e
	}
	s.planningValidationSignals(&w, beforePlanning, kind, event)
	if e = validatePlanningState(&w); e != nil {
		return w, e
	}
	w.Revision++
	w.Updated = now()
	b, e := json.Marshal(w)
	if e != nil {
		return w, e
	}
	if create {
		_, e = tx.Exec("INSERT INTO works VALUES(?,?,?)", w.ID, w.Revision, b)
	} else {
		var r sql.Result
		r, e = tx.Exec("UPDATE works SET revision=?,body=? WHERE id=? AND revision=?", w.Revision, b, w.ID, expected)
		if e == nil {
			n, _ := r.RowsAffected()
			if n != 1 {
				e = fmt.Errorf("conflit de révision")
			}
		}
	}
	if e != nil {
		return w, e
	}
	if hook != nil {
		if e = hook(tx, &w); e != nil {
			return w, e
		}
	}
	_, e = tx.Exec("INSERT INTO events VALUES(?,?,?,?,?,?,?)", event, w.ID, w.Revision, kind, w.Updated, request, request)
	if e != nil {
		return w, e
	}
	e = tx.Commit()
	return w, e
}
func (s *Store) apply(w *Work, kind string, r Request) error {
	switch kind {
	case "work.update":
		return updateWorkDefinition(w, r)
	case "work.create":
		if !nonempty(r.Title) || !nonempty(r.Objective) || !nonempty(r.Scope) || len(r.Criteria) == 0 {
			return fmt.Errorf("title, objective, scope et criteria requis")
		}
		w.Title = r.Title
		w.Objective = r.Objective
		w.Scope = r.Scope
		w.Criteria = r.Criteria
		w.RequirementPrerequisites = r.RequirementPrerequisites
		if e := validateRequirementPrerequisites(w); e != nil {
			return e
		}
		w.Next = r.Next
		w.Git = gitState(s.root)
	case "task.add":
		if !safeName(r.ID) || !nonempty(r.Title) || !nonempty(r.Deliverable) || len(r.Criteria) == 0 {
			return fmt.Errorf("id, title, deliverable et criteria requis")
		}
		if _, e := w.task(r.ID); e == nil {
			return fmt.Errorf("tâche déjà présente")
		}
		for _, dep := range r.Depends {
			if _, e := w.task(dep); e != nil {
				return e
			}
		}
		w.Tasks = append(w.Tasks, Task{ID: r.ID, Title: r.Title, Deliverable: r.Deliverable, Criteria: r.Criteria, Owner: r.Owner, Depends: r.Depends, Status: "todo", Next: r.Next, Attempts: []Attempt{}})
	case "task.update":
		t, e := w.task(r.ID)
		if e != nil {
			return e
		}
		if e = updateTaskDefinition(w, t, r); e != nil {
			return e
		}
		if r.Status == "" {
			// Metadata edits do not re-accept or relaunch a task, and must not
			// erase a blocker or demand fresh gates merely to change its owner.
			if r.Owner != "" {
				t.Owner = r.Owner
			}
			if r.Next != "" {
				if err := updateTaskInstructions(t, r.Next); err != nil {
					return err
				}
			}
			if r.Blocker != "" {
				t.Blocker = r.Blocker
			}
			return nil
		}
		if status(r.Status) == "" {
			return fmt.Errorf("statut inconnu")
		}
		transitions := map[string]string{"todo": "running blocked abandoned", "running": "submitted blocked todo abandoned", "blocked": "todo running abandoned", "submitted": "accepted running blocked abandoned", "accepted": "todo", "waived": "todo", "abandoned": "todo"}
		if r.Status != t.Status && !strings.Contains(" "+transitions[t.Status]+" ", " "+r.Status+" ") {
			return &CommandError{Code: "invalid_transition", Message: fmt.Sprintf("transition refusée : %s → %s", t.Status, r.Status)}
		}
		if r.Status == "running" || r.Status == "accepted" {
			if e := s.requirementPrerequisiteGuard(w, t); e != nil {
				return e
			}
			for _, dep := range t.Depends {
				d, _ := w.task(dep)
				if !s.acceptedFresh(w, d, map[string]bool{}) {
					return fmt.Errorf("dépendance non validée ou périmée : %s", dep)
				}
			}
		}
		if r.Status == "accepted" {
			if e := s.independentReviewGuard(w, t); e != nil {
				return e
			}
		}
		if r.Status == "accepted" && !s.validGate(t) {
			return fmt.Errorf("acceptation refusée : gate delivery courante requise")
		}
		if r.Status == "blocked" && !nonempty(r.Blocker) {
			return fmt.Errorf("motif du blocage requis")
		}
		if t.Status == "running" && r.Status != "running" {
			if r.Outcome != "completed" && r.Outcome != "interrupted" && r.Outcome != "failed" {
				return fmt.Errorf("outcome requis : completed, interrupted, failed")
			}
			if r.Status == "submitted" && r.Outcome != "completed" {
				return fmt.Errorf("soumission : outcome completed requis")
			}
			a := &t.Attempts[len(t.Attempts)-1]
			a.Status = r.Outcome
			a.Ended = now()
		}
		if r.Status == "running" && t.Status != "running" {
			if t.IndependentReview != nil && (t.IndependentReview.State == "running" || t.IndependentReview.State == "queued") {
				return fmt.Errorf("revue indépendante active ; terminer sa conduite avant une nouvelle production")
			}
			archiveIndependentReview(t)
			t.BatchReviewResume = nil
			t.ReviewCoordination = nil
			t.Attempts = append(t.Attempts, Attempt{ID: newID("a-"), Status: "recorded", Started: now()})
			t.Gate = nil
			t.EvidenceStaleReason = ""
			// Une correction est une nouvelle production : la décision et la
			// preuve de la tentative précédente restent dans leur reçu, mais ne
			// doivent plus apparaître comme la validation courante de la tâche.
			t.AutoValidation = nil
		}
		if r.Status == "todo" && t.Status != r.Status {
			if t.Status == "accepted" && !s.acceptedFresh(w, t, map[string]bool{}) && t.Gate != nil {
				t.Revalidation = &Revalidation{PreviousArtifacts: t.Gate.Evaluation.Artifacts, Config: t.Gate.Evaluation.ConfigDigest}
			}
			t.Gate = nil
			t.EvidenceStaleReason = ""
			t.Override = nil
		}
		t.Status = r.Status
		t.Blocker = r.Blocker
		if r.Next != "" {
			t.Next = r.Next
		}
		if r.Owner != "" {
			t.Owner = r.Owner
		}
	case "checkpoint":
		if !nonempty(r.Summary) {
			return fmt.Errorf("summary requis")
		}
		w.Summary = r.Summary
		w.Next = r.Next
		for _, p := range r.Memory {
			if _, e := localFile(s.root, p); e != nil {
				return e
			}
		}
		w.Memory = r.Memory
		w.Git = gitState(s.root)
	case "ooda":
		if !nonempty(r.Observation) || !nonempty(r.Orientation) || !nonempty(r.Decision) || !nonempty(r.Owner) || !nonempty(r.Next) {
			return fmt.Errorf("OODA : observation, orientation, decision, owner et next requis")
		}
		w.Next = r.Next
		if r.Result != "" {
			w.Summary = r.Result
		}
	default:
		return fmt.Errorf("opération inconnue")
	}
	return nil
}

// Every top-level read gets new physical fingerprints. Nested reads share them,
// so common proofs are read once even when many gates reference the same binary.
func (s *Store) readScope() *Store {
	if s.readDigests != nil {
		return s
	}
	clone := *s
	clone.readDigests = map[string]string{}
	clone.readReviews = map[string]error{}
	return &clone
}
"}

{"path":"internal/engine/cockpit_service.go","git_blob":"ea5a9228a49258a55e9004ac2bf4bc845aa656de","sha256":"10a8dfa137035a50a808d333a4befbb2596760bbe3b406ad1ce4e80b171770b1","bytes":1775,"content":"package engine

import (
	"encoding/json"
	"errors"
	"syscall"
)

// Machine-readable code is stable; the French message is shared by terminal and CLI.
type CommandError struct {
	Code      string `json:"code"`
	Message   string `json:"message"`
	Retryable bool   `json:"retryable"`
}

func (e *CommandError) Error() string { return e.Message }
func commandFailure(err error) *CommandError {
	var e *CommandError
	if errors.As(err, &e) {
		return e
	}
	var sqliteCode interface{ Code() int }
	if errors.Is(err, syscall.ENOSPC) || (errors.As(err, &sqliteCode) && sqliteCode.Code()&255 == 13) {
		return &CommandError{Code: "storage_unavailable", Message: "Écriture impossible : stockage plein. Libérez de l’espace puis vérifiez l’état de la mission avant de reprendre ; aucun résultat n’est validé par cette erreur."}
	}
	var preparation *PreparationError
	if errors.As(err, &preparation) {
		retryable := preparation.Code == "conflict" || preparation.Code == "provider_unavailable" || preparation.Code == "interrupted"
		return &CommandError{Code: preparation.Code, Message: preparation.Message, Retryable: retryable}
	}
	return &CommandError{Code: "command_failed", Message: err.Error()}
}
func (s *Store) executeRequest(work, kind string, r Request) (Work, error) {
	if r.Schema != 1 {
		return Work{}, &CommandError{Code: "invalid_schema", Message: "schema_version doit valoir 1"}
	}
	switch kind {
	case "work.create", "work.update", "task.add", "task.update", "checkpoint", "ooda":
	default:
		return Work{}, &CommandError{Code: "unknown_command", Message: "opération inconnue"}
	}
	raw, e := json.Marshal(r)
	if e != nil {
		return Work{}, e
	}
	return s.mutate(work, kind, r.EventID, r.Revision, raw, func(w *Work) error { return s.apply(w, kind, r) })
}
"}

{"path":"internal/engine/review_timeout_test.go","git_blob":"0292c217255316e3ee471cb3186fde407461e3f7","sha256":"a00d54806db0d5e905a3b8f3b0bde0930fc4a47535acd9d461bf325e2493c752","bytes":4834,"content":"//go:build linux

package engine

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"time"
)

func TestReviewTimeoutConfigurationPreservesBudgetAndHistory(t *testing.T) {
	s, w := managedFixture(t)
	original := *w.Planning.Reviewer
	if seconds, err := reviewTimeoutSeconds(w.Planning.Reviewer); err != nil || seconds != 0 {
		t.Fatal(seconds, err)
	}
	for _, seconds := range []int64{-1, int64(^uint64(0)>>1)/int64(time.Second) + 1} {
		raw, err := json.Marshal(map[string]any{"schema_version": 1, "event_id": newID("invalid-"), "expected_revision": w.Revision, "review_timeout_seconds": seconds, "reason": "Explicit fixture configuration"})
		if err != nil {
			t.Fatal(err)
		}
		var request PlanningRequest
		err = strict(raw, &request)
		if err == nil {
			_, err = s.planningChange(w.ID, "review-timeout", request)
		}
		if err == nil {
			t.Fatalf("invalid timeout accepted: %d", seconds)
		}
	}
	r := PlanningRequest{Schema: 1, EventID: "set-review-timeout", Revision: w.Revision, ReviewTimeoutSeconds: 300, Reason: "Explicit operator adjustment for a longer review"}
	file := filepath.Join(t.TempDir(), "request.json")
	data, _ := json.Marshal(r)
	os.WriteFile(file, data, 0600)
	var out bytes.Buffer
	if err := s.planningCLI([]string{"planning", "review-timeout", w.ID}, file, &out); err != nil {
		t.Fatal(err)
	}
	after, err := s.get(w.ID)
	if err != nil {
		t.Fatal(err)
	}
	want := original
	want.TimeoutSeconds = 300
	if !reflect.DeepEqual(*after.Planning.Reviewer, want) || !reflect.DeepEqual(w.Tasks, after.Tasks) {
		t.Fatal("configuration changed budget or task history")
	}
	replay, err := s.planningChange(w.ID, "review-timeout", r)
	if err != nil || replay.Revision != after.Revision {
		t.Fatal("configuration not idempotent", err)
	}
	r.EventID = "stale-revision"
	if _, err := s.planningChange(w.ID, "review-timeout", r); err == nil {
		t.Fatal("stale revision accepted")
	}
	reopened, err := openStore(s.root, false)
	if err != nil {
		t.Fatal(err)
	}
	defer reopened.db.Close()
	w, err = reopened.get(w.ID)
	if err != nil || w.Planning.Reviewer.TimeoutSeconds != 300 {
		t.Fatal("timeout not durable", err)
	}
	w.Tasks[0].IndependentReview = &IndependentReview{ID: "active-review", State: "running", TimeoutSeconds: 300}
	body, _ := json.Marshal(w)
	s.db.Exec("UPDATE works SET body=? WHERE id=?", body, w.ID)
	r.EventID = "cannot-change-active"
	r.Revision = w.Revision
	r.ReviewTimeoutSeconds = 600
	if _, err := s.planningChange(w.ID, "review-timeout", r); err == nil {
		t.Fatal("active deadline changed")
	}
}

func TestManagedReviewTimeoutRetryReusesCandidateWithoutRefund(t *testing.T) {
	s, w := managedFixture(t)
	base := w.Planning.Repository.Candidate
	fixture := filepath.Join(s.root, "review-fixture", "claude")
	data, err := os.ReadFile(fixture)
	if err != nil {
		t.Fatal(err)
	}
	data = bytes.Replace(data, []byte("text=sys.stdin.read()"), []byte("import time\ntext=sys.stdin.read()\ntime.sleep(2)"), 1)
	if err = os.WriteFile(fixture, data, 0700); err != nil {
		t.Fatal(err)
	}
	w, err = s.planningChange(w.ID, "review-timeout", PlanningRequest{Schema: 1, EventID: "short-review", Revision: w.Revision, ReviewTimeoutSeconds: 1, Reason: "Fixture reproduces bounded review timeout"})
	if err != nil {
		t.Fatal(err)
	}
	a := managedCompleted(t, s, w, "first", "timeout candidate\n")
	if err = s.integrateManagedAttempt(a); err != nil {
		t.Fatal(err)
	}
	w, _ = s.get(w.ID)
	task, _ := w.task("first")
	first := *task.IndependentReview
	if first.State != "error" || first.TimeoutSeconds != 1 || !strings.Contains(first.Reason, "délai") || w.Planning.Repository.Candidate != base || w.Planning.Reviewer.Calls != 1 {
		t.Fatalf("deadline not enforced: %+v", first)
	}
	w, err = s.planningChange(w.ID, "review-timeout", PlanningRequest{Schema: 1, EventID: "longer-review", Revision: w.Revision, ReviewTimeoutSeconds: 4, Reason: "Explicit longer deadline after reproduced timeout"})
	if err != nil {
		t.Fatal(err)
	}
	if w.Tasks[0].IndependentReview.ID != first.ID || w.Planning.Reviewer.Calls != 1 {
		t.Fatal("changing timeout erased review")
	}
	w, err = s.planningChange(w.ID, "retry-review", PlanningRequest{Schema: 1, EventID: "explicit-timeout-retry", Revision: w.Revision, Task: "first", Reason: "Deadline corrected from one second to four; candidate unchanged"})
	if err != nil {
		t.Fatal(err)
	}
	if err = s.integrateManagedAttempt(a); err != nil {
		t.Fatal(err)
	}
	w, _ = s.get(w.ID)
	task, _ = w.task("first")
	second := task.IndependentReview
	if second.State != "passed" || second.TimeoutSeconds != 4 || second.ID == first.ID || second.CandidateSHA != first.CandidateSHA || len(task.Attempts) != 1 || w.Planning.Reviewer.Calls != 2 || task.Status != "accepted" {
		t.Fatalf("retry changed candidate/history or failed: %+v", task)
	}
}
